@dataclass(frozen=True)
class Config:
    max_decisions: int = 15
    model_timeout: float = 60
    execution_timeout: float = 180
    max_tool_calls: int = 16

    def __post_init__(self):
        if type(self.max_decisions) is not int or not 1 <= self.max_decisions <= 15:
            raise ValueError("max_decisions must be between 1 and 15")
        if type(self.max_tool_calls) is not int or not 1 <= self.max_tool_calls <= 16:
            raise ValueError("max_tool_calls must be between 1 and 16")
        if any(
            not math.isfinite(v) or v <= 0
            for v in (self.model_timeout, self.execution_timeout)
        ):
            raise ValueError("Timeouts must be finite and positive")
